(() => {
  const M=window.MiCoinsModel,v=document.body.dataset.variant,phone=document.querySelector('#phone'),sheet=document.querySelector('#sheet'),content=document.querySelector('#sheet-content');
  const base='../assets/final/',fmt=n=>n.toLocaleString('en-US'),key='mi-coins-prototype-v1';
  let state=M.initial(),selected=v==='A'?'ali3000':null,lastFocus;
  try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved.pubgDone==='boolean')state=saved.pubgDone?M.complete(M.initial()):M.initial();}catch{}
  const asset=name=>base+'a-'+name;
  const coin=()=>`<img class="coin" alt="" src="${asset('imgC6Ae51537A4140D9861B9818703543F01.png')}">`;
  const text=(value,x,y,size,extra='')=>`<span class="text ${extra}" style="left:${x}px;top:${y}px;font-size:${size}px">${value}</span>`;
  const game=id=>`<div class="game-art ${id}"><img src="${asset('imgImage7.png')}" alt=""></div>`;
  function hero(){return `<div class="art-background"><img src="${base+(v==='A'?'a-imgGroup41.png':'b-imgGroup41.png')}" alt=""></div>${text('2 : 36',16,14,10)}<img style="position:absolute;left:352px;top:15.945px;width:23.998px;height:13.667px" alt="Battery" src="${asset('imgGroup2.svg')}"><img style="position:absolute;left:300px;top:15.945px;width:19px;height:13.667px" alt="Mobile signal" src="${asset('imgGroup1.svg')}"><img style="position:absolute;left:327px;top:15.945px;width:17px;height:13.667px" alt="Wi-Fi" src="${asset('imgVector.svg')}"><button class="icon-button" data-action="back" aria-label="Back to case study" style="left:24px;top:56px;width:17px;height:8px"><img alt="" src="${asset('imgVector1.svg')}"></button>${text('Mi Coins',161,53,18,'title')}<button class="icon-button" data-action="info" aria-label="About this prototype" style="left:354px;top:${v==='A'?50.408:58.335}px;width:13px;height:${v==='A'?12.364:14.308}px"><img alt="" src="${asset('imgGroup3.svg')}"></button>${text('Balance',16,108,12,'muted')}${text(fmt(state.balance),16,137,34,'hero-balance')}${text('Mi Coins',118,152,14,'orange')}<button class="text plain muted" data-action="history" style="left:16px;top:183px;font-size:12px;text-decoration:underline">History</button><img style="position:absolute;left:61px;top:186px;width:12px;height:6px;transform:rotate(180deg)" alt="" src="${asset('imgVector2.svg')}">${text('Use your coins toward real rewards.',16,214,10,'muted')}`;}
  function rewards(){return `<div class="panel rewards-panel"><span class="panel-kicker text">${v==='A'?'01 / VALUE':'03 / VALUE'}</span><span class="panel-title text">Redeem Rewards</span><button class="view-all plain" data-action="rewards">View all <img alt="" src="${asset('imgVector3.svg')}"></button><div class="reward-rail" aria-label="Redeem rewards: swipe horizontally">${M.rewards.map(r=>{const g=M.goal(state,r.id);return `<button class="reward-card ${r.id==='recharge'?'blue':''}" data-reward="${r.id}" aria-label="${r.face} rubles ${r.name}, ${fmt(r.cost)} Mi Coins, ${g.gap?fmt(g.gap)+' coins short':'eligible by balance'}"><div class="reward-media"></div><div class="reward-art ${r.art}"><img draggable="false" alt="${fmt(r.face)} ₽ ${r.name}" src="${base+r.asset}"></div><span class="text reward-name">${r.id==='recharge'?'Recharge':r.name}</span><span class="text reward-face">${fmt(r.face)} ₽</span>${coin()}<span class="text reward-points">${fmt(r.cost)} Mi Coins</span>${v==='B'?`<span class="eligibility ${g.gap?'short':''}">${g.gap?'Insufficient coins':'Threshold met'}</span>${g.gap?`<span class="text card-gap">${fmt(g.gap)} short</span>`:''}`:''}</button>`}).join('')}</div></div>`;}
  function goal(){const g=M.goal(state,selected);return `<div class="panel goal-panel ${g?'chosen':''}">${v==='B'?'<span class="panel-kicker text">04 / REWARD GUIDANCE</span>':''}<span class="text goal-heading">Choose a reward goal</span><span class="text goal-subtitle">Select an existing reward to see your progress.</span><button class="choose" data-action="choose">Choose reward${v==='A'?`<img alt="" src="${asset('imgVector4.svg')}">`:''}</button>${g?`<div class="goal-inner"><div class="goal-thumb"><img alt="" src="${base+g.asset}"></div><span class="text goal-name">${g.name}</span><span class="text goal-face">${fmt(g.face)} ₽ · ${fmt(g.cost)} Mi Coins</span><button class="goal-status" data-action="${g.gap?'earn':'redeem'}">${g.gap?'Insufficient coins':'Redeem reward'}</button><div class="track" role="progressbar" aria-label="Reward goal progress" aria-valuenow="${Math.round(g.progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${g.progress}%"></i></div><span class="text goal-fraction"><span class="orange">${fmt(state.balance)}</span> / ${fmt(g.cost)}</span><span class="text goal-gap">${g.gap?fmt(g.gap)+' short':'Ready to redeem'}</span></div>`:''}</div>`;}
  function tasks(){const order=v==='A'?['ml','pubg','cod','mono']:['pubg','cod','mono','ml'],ys=v==='A'?[70,141,208,275]:[70,141,210,278];return `<div class="panel tasks-panel"><span class="panel-kicker text">${v==='A'?'02 / ACTION & PROGRESS':'02 / ACTION'}</span><span class="panel-title text">Earn Mi Coins</span>${order.map((id,i)=>{const t=M.tasks.find(t=>t.id===id),s=id==='pubg'&&state.pubgDone?'completed':t.status;return `<div class="task-row" style="top:${ys[i]}px">${game(id)}<span class="text task-name">${t.name}</span><span class="text task-requirement">Download and Active</span>${coin()}<span class="text task-reward">+ 100 Mi Coins</span><span class="task-status ${s}">${s==='completed'?`<img alt="" src="${asset('imgVector8.svg')}">Completed`:s==='progress'?'50% · In Progress':'No Started'}</span><button class="task-action ${s==='progress'?'continue':''}" data-task="${id}">${s==='progress'?'Continue':s==='completed'?(id==='pubg'?'Completed':'Pending'):'Start task'}</button></div>${i<3?`<div class="separator" style="top:${ys[i]+59}px"></div>`:''}`}).join('')}</div>`;}
  function current(){return `<div class="panel current-panel"><span class="panel-kicker text">01 / PROGRESS</span><span class="panel-title text">Current Task Progress</span><div class="current-task">${game('pubg')}<span class="text task-name">PUBG Mobile</span><span class="text task-requirement">+100 Mi Coins · Download and Active</span><button class="task-action continue" data-task="pubg">${state.pubgDone?'Completed':'Continue'}</button></div><span class="text current-state">${state.pubgDone?'Completed':'In Progress'}</span><span class="text current-percent">${state.pubgDone?'100%':'50%'}</span><div class="track" role="progressbar" aria-label="PUBG progress" aria-valuenow="${state.pubgDone?100:50}" aria-valuemin="0" aria-valuemax="100"><i style="width:${state.pubgDone?100:50}%"></i></div></div>`;}
  function render(){const oldScroll=phone.querySelector('.reward-rail')?.scrollLeft||0;phone.innerHTML=hero()+(v==='A'?rewards()+goal()+tasks():current()+tasks()+rewards()+goal());phone.classList.toggle('has-goal',v==='B'&&!!selected);phone.querySelector('.title').style.fontWeight='700';phone.querySelector('.reward-rail').scrollLeft=oldScroll;dragRail();fit();}
  function fit(){const scale=Math.min(1,document.documentElement.clientWidth/392),box=document.querySelector('#scale-box');phone.style.transform=`scale(${scale})`;box.style.width=392*scale+'px';box.style.height=phone.offsetHeight*scale+'px';}
  function open(html){lastFocus=document.activeElement;content.innerHTML=html;sheet.showModal();sheet.querySelector('.sheet-close').focus();}
  function close(){if(sheet.open)sheet.close();lastFocus?.focus();}
  function rewardPicker(){open(`<span class="demo-label">Prototype Simulation</span><h2 id="sheet-title">Choose a reward</h2><p>Balance: <b>${fmt(state.balance)} Mi Coins</b>. Select an existing reward as your goal.</p>${M.rewards.map(r=>{const g=M.goal(state,r.id);return `<button class="sheet-reward" data-select="${r.id}"><span><b>${fmt(r.face)} ₽ ${r.name}</b><small>${fmt(r.cost)} Mi Coins</small></span><span>${g.gap?fmt(g.gap)+' short':'Redeemable'}</span></button>`}).join('')}<p>Eligibility here uses the coin balance only. No real redemption is submitted.</p>`);}
  function taskSheet(id){const t=M.tasks.find(t=>t.id===id);open(`<span class="demo-label">Prototype Simulation · Demo</span><h2 id="sheet-title">${t.name}</h2><p><b>+100 Mi Coins</b><br>Download and Activate<br>${id==='pubg'?'Progress: '+(state.pubgDone?'100% · Completed':'50% · In Progress'):t.status==='completed'?'Completed · reward status Pending':'Not Started'}</p><p>Demo: open the game to continue the activation task. Detailed steps, eligibility and credit timing require confirmation; this prototype is not connected to GetApps.</p>${id==='pubg'?`<button class="primary" data-action="complete" ${state.pubgDone?'disabled':''}>${state.pubgDone?'Simulation completed':'Simulate completion'}</button><p>This optional demo credits 100 coins once. It does not perform a real download or activation.</p>`:`<button class="primary" data-action="task-demo">${t.status==='completed'?'View reward status':'Preview task action'}</button>`}`);}
  function animateUpdate(old){render();requestAnimationFrame(()=>{if(selected){const fill=phone.querySelector('.goal-inner .track i'),before=M.goal(old,selected);fill.style.transition='none';fill.style.width=before.progress+'%';requestAnimationFrame(()=>{fill.style.transition='width 400ms ease-out';fill.style.width=M.goal(state,selected).progress+'%';});}const currentFill=phone.querySelector('.current-panel>.track i');if(currentFill){currentFill.style.transition='none';currentFill.style.width=(old.pubgDone?100:50)+'%';requestAnimationFrame(()=>{currentFill.style.transition='width 400ms ease-out';currentFill.style.width=(state.pubgDone?100:50)+'%';});}});}
  function selectGoal(id){const before=M.goal(state,selected)?.progress||0;selected=id;render();const fill=phone.querySelector('.goal-inner .track i');fill.style.transition='none';fill.style.width=before+'%';requestAnimationFrame(()=>requestAnimationFrame(()=>{fill.style.transition='width 400ms ease-out';fill.style.width=M.goal(state,selected).progress+'%';}));}
  function action(e){const pick=e.target.closest('[data-select]');if(pick){close();selectGoal(pick.dataset.select);return;}const r=e.target.closest('[data-reward]');if(r){if(!dragged)selectGoal(r.dataset.reward);return;}const task=e.target.closest('[data-task]');if(task){taskSheet(task.dataset.task);return;}const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case'choose':case'rewards':rewardPicker();break;case'complete':{const old={...state};state=M.complete(state);try{localStorage.setItem(key,JSON.stringify(state));}catch{}close();animateUpdate(old);if(!old.pubgDone){const f=document.querySelector('#feedback');f.textContent='+100 Mi Coins · Demo';f.classList.add('active');setTimeout(()=>{f.classList.remove('active');f.textContent='';},1800);}break;}case'earn':phone.querySelector('.tasks-panel').scrollIntoView({behavior:'smooth',block:'start'});break;case'redeem':open('<span class="demo-label">Prototype Simulation</span><h2 id="sheet-title">Ready to redeem</h2><p>Your balance meets this reward’s coin threshold. This demo does not submit an order or deduct coins. Inventory and full eligibility are unverified.</p><button class="primary" data-action="close">Back to Mi Coins</button>');break;case'history':open(`<span class="demo-label">Prototype Simulation</span><h2 id="sheet-title">History</h2><p>${state.pubgDone?'Demo only: PUBG completion +100 Mi Coins. Current simulated balance: 8,353.':'No real transaction history was supplied. Balance: 8,253 Mi Coins.'}</p>`);break;case'info':open('<span class="demo-label">Prototype Simulation</span><h2 id="sheet-title">About this prototype</h2><p>High-Fidelity UI designed in Figma by the designer. Interactive web prototype implemented with AI assistance.</p><p>All interactions are local demonstrations. PUBG completion adds 100 simulated coins once. A and B share the simulated balance.</p><button class="secondary" data-action="reset">Reset simulation</button>');break;case'reset':state=M.initial();try{localStorage.removeItem(key);}catch{}close();render();break;case'task-demo':open('<span class="demo-label">Demo · No real activation</span><h2 id="sheet-title">Task action preview</h2><p>In the product, this action would lead to task instructions or activation. No external game is launched here, and no unverified completion steps are presented as real rules.</p>');break;case'close':close();break;case'back':if(parent!==window)parent.postMessage({type:'mi-final-back'},location.protocol==='file:'?'*':location.origin);else location.href='../index.html#design';break;}}
  let dragged=false;function dragRail(){const rail=phone.querySelector('.reward-rail');let startX,startLeft,down=false;rail.addEventListener('pointerdown',e=>{dragged=false;if(e.pointerType!=='mouse')return;down=true;startX=e.clientX;startLeft=rail.scrollLeft;});rail.addEventListener('pointermove',e=>{if(!down)return;if(Math.abs(e.clientX-startX)>4){dragged=true;rail.classList.add('dragging');rail.scrollLeft=startLeft-(e.clientX-startX);e.preventDefault();}});const end=()=>{down=false;rail.classList.remove('dragging');setTimeout(()=>dragged=false,0)};rail.addEventListener('pointerup',end);rail.addEventListener('pointerleave',end);rail.addEventListener('dragstart',e=>e.preventDefault());}
  document.addEventListener('click',action);sheet.querySelector('.sheet-close').onclick=close;sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});sheet.addEventListener('close',()=>lastFocus?.focus());addEventListener('resize',fit);addEventListener('storage',e=>{if(e.key===key){const old=state;try{const next=JSON.parse(e.newValue);state=next?.pubgDone?M.complete(M.initial()):M.initial();}catch{state=M.initial()}animateUpdate(old);}});document.fonts.ready.then(fit);render();
})();
